fun ShoppingBagFlight(product:ShopProduct,start:Offset,end:Offset,progress:Float) {
    ServerAssetImage(product.photos.firstOrNull(),product.name,Modifier.size(72.dp).graphicsLayer{
        val t=progress.coerceIn(0f,1f)
