fun MotionButton(onClick:()->Unit,modifier:Modifier=Modifier,enabled:Boolean=true,shape:Shape=CircleShape,colors:ButtonColors=ButtonDefaults.buttonColors(),content:@Composable RowScope.()->Unit) {
    val source=remember{MutableInteractionSource()};val pressed by source.collectIsPressedAsState()
    val scale by animateFloatAsState(if(pressed).97f else 1f,if(LocalMotion.current)spring(.8f,650f) else snap(),label="button-press")
    val background=if(enabled)colors.containerColor else colors.disabledContainerColor
    val foreground=if(enabled)colors.contentColor else colors.disabledContentColor
    Row(modifier.heightIn(min=48.dp).graphicsLayer{scaleX=scale;scaleY=scale}.clip(shape).background(background)
        .clickable(interactionSource=source,indication=null,enabled=enabled,role=Role.Button,onClick=onClick).padding(horizontal=20.dp,vertical=10.dp),
        verticalAlignment=androidx.compose.ui.Alignment.CenterVertically,horizontalArrangement=Arrangement.Center) {
        CompositionLocalProvider(LocalContentColor provides foreground){ProvideTextStyle(MaterialTheme.typography.labelLarge){content()}}

fun PaymentExperience(amount:Long,recipient:String,successTitle:String,onCommit:suspend ()->Boolean,autoCloseOnSuccess:Boolean=false,embedded:Boolean=false,errorMessage:String?=null,confirmed:Boolean?=null,onClose:()->Unit) {
    var result by rememberSaveable { mutableStateOf<Boolean?>(null) }
    var authenticated by rememberSaveable{mutableStateOf(false)}
    val scanUntil by rememberSaveable { mutableLongStateOf(android.os.SystemClock.elapsedRealtime()+kotlin.random.Random.nextLong(1000L,3001L)) }
    var completed by rememberSaveable { mutableStateOf(false) }
    var commitError by rememberSaveable{mutableStateOf<String?>(null)}
    // A recovered success is authoritative, but does not skip the remaining visual scan.
    LaunchedEffect(confirmed){if(confirmed==true)result=true}
    val commit by rememberUpdatedState(onCommit)
    LaunchedEffect(Unit){if(!authenticated){delay((scanUntil-android.os.SystemClock.elapsedRealtime()).coerceAtLeast(0));authenticated=true}}
    // The caller has already confirmed payment. Persist an early response immediately
    // so recreating the page during its scan cannot submit an already-finished payment again.
    LaunchedEffect(Unit){
        if(result==null&&confirmed!=true){
            try{val outcome=commit();if(result!=true)result=outcome}
            catch(cancelled:kotlinx.coroutines.CancellationException){throw cancelled}
            catch(error:Exception){if(result!=true){commitError=error.message ?: "结果待确认，请在钱包或订单中查看";result=false}}
        }
    }
    val visibleResult=if(authenticated)result else null
    val close by rememberUpdatedState(onClose)
    LaunchedEffect(completed,result) { if(completed&&result==true&&autoCloseOnSuccess){delay(850);close()} }

fun PaymentConfirmation(modifier:Modifier,play:Boolean=true,waiting:Boolean=false,authenticating:Boolean=false,onComplete:()->Unit) {
    val context=LocalContext.current
    var movie by remember { mutableStateOf(FacePayAssets.movie) }
    LaunchedEffect(Unit) { PaymentSound.prepare(context);movie=FacePayAssets.load(context) }
    val frame=remember { Animatable(if(authenticating)0f else 21f) }
    val motion=LocalMotion.current
    val haptic=LocalHapticFeedback.current
    val complete by rememberUpdatedState(onComplete)
    var sounded by rememberSaveable { mutableStateOf(false) }
    LaunchedEffect(play,waiting,authenticating,motion) {
        if(!play){frame.snapTo(27f);return@LaunchedEffect}
        if(authenticating){
            if(motion)frame.animateTo(5f,tween(180,easing=LinearEasing)) else frame.snapTo(0f)
            return@LaunchedEffect
        }
        if(waiting) {
            if(!motion){frame.snapTo(21f);return@LaunchedEffect}
            frame.animateTo(21f,tween(((21f-frame.value).coerceAtLeast(0f)*33.333f).roundToInt(),easing=LinearEasing))
            while(isActive){frame.snapTo(9f);frame.animateTo(21f,tween(400,easing=LinearEasing))}
            return@LaunchedEffect
        }
        if(motion)frame.animateTo(27f,tween(((27f-frame.value).coerceAtLeast(0f)*33.333f).roundToInt(),easing=LinearEasing))
        else frame.snapTo(27f)
        delay(if(motion)140 else 70)
        if(!sounded){sounded=true;PaymentSound.confirm();haptic.performHapticFeedback(HapticFeedbackType.Confirm)}
        delay(if(motion)130 else 70)
        complete()
    }
    Canvas(modifier) {
        val asset=movie ?: return@Canvas
        val index=frame.value.roundToInt().coerceIn(0,asset.frames.lastIndex)
        val layers=asset.frames[index]
        val side=minOf(size.width,size.height,188.dp.toPx())
        if(index<22) {
            val tile=asset.viewport.roundToInt()
            drawImage(asset.atlas,srcOffset=androidx.compose.ui.unit.IntOffset(index%6*tile,index/6*tile),srcSize=androidx.compose.ui.unit.IntSize(tile,tile),
                dstOffset=androidx.compose.ui.unit.IntOffset(((size.width-side)*.5f).roundToInt(),((size.height-side)*.5f).roundToInt()),
                dstSize=androidx.compose.ui.unit.IntSize(side.roundToInt(),side.roundToInt()),filterQuality=androidx.compose.ui.graphics.FilterQuality.High)
            return@Canvas
        }
        translate((size.width-side)*.5f,(size.height-side)*.5f) {
            scale(side/asset.viewport,pivot=androidx.compose.ui.geometry.Offset.Zero) {
                layers.forEach { drawPath(it.path,it.color) }
            }
        }

